//! Bare-Metal `#![no_std]` PNG / JPG / BMP Decoder, Smooth Bicubic/Bilinear Wallpaper Engine,
//! and 8x-Supersampled (Lanczos Anti-Aliased) 32-bit RGBA Icons & Multi-State Cursors (`src/image_codec.rs`)

#![allow(dead_code)]

extern crate alloc;
use alloc::vec;
use alloc::vec::Vec;

#[derive(Clone)]
pub struct DecodedImage {
    pub width: usize,
    pub height: usize,
    pub pixels: Vec<u32>,
}

impl DecodedImage {
    /// Bilinearly scales this `DecodedImage` with 16.8 fixed-point precision to `(dst_w, dst_h)`
    pub fn scale_adaptive(&self, dst_w: usize, dst_h: usize) -> DecodedImage {
        if self.width == 0 || self.height == 0 || self.pixels.is_empty() {
            return generate_builtin_wallpaper(0, dst_w, dst_h);
        }
        if self.width == dst_w && self.height == dst_h {
            return self.clone();
        }

        let mut out = vec![0u32; dst_w.saturating_mul(dst_h)];
        let src_w = self.width;
        let src_h = self.height;

        for dy in 0..dst_h {
            let sy_fp = (dy * (src_h.saturating_sub(1)) * 256) / dst_h.max(1);
            let sy0 = (sy_fp >> 8).min(src_h - 1);
            let sy1 = (sy0 + 1).min(src_h - 1);
            let fy = (sy_fp & 0xFF) as u32;
            let inv_fy = 256 - fy;

            let row0 = sy0 * src_w;
            let row1 = sy1 * src_w;
            let dst_row = dy * dst_w;

            for dx in 0..dst_w {
                let sx_fp = (dx * (src_w.saturating_sub(1)) * 256) / dst_w.max(1);
                let sx0 = (sx_fp >> 8).min(src_w - 1);
                let sx1 = (sx0 + 1).min(src_w - 1);
                let fx = (sx_fp & 0xFF) as u32;
                let inv_fx = 256 - fx;

                let p00 = self.pixels[row0 + sx0];
                let p10 = self.pixels[row0 + sx1];
                let p01 = self.pixels[row1 + sx0];
                let p11 = self.pixels[row1 + sx1];

                let w00 = inv_fx * inv_fy;
                let w10 = fx * inv_fy;
                let w01 = inv_fx * fy;
                let w11 = fx * fy;

                let r = (((p00 >> 16) & 0xFF) * w00
                    + ((p10 >> 16) & 0xFF) * w10
                    + ((p01 >> 16) & 0xFF) * w01
                    + ((p11 >> 16) & 0xFF) * w11)
                    >> 16;
                let g = (((p00 >> 8) & 0xFF) * w00
                    + ((p10 >> 8) & 0xFF) * w10
                    + ((p01 >> 8) & 0xFF) * w01
                    + ((p11 >> 8) & 0xFF) * w11)
                    >> 16;
                let b = ((p00 & 0xFF) * w00
                    + (p10 & 0xFF) * w10
                    + (p01 & 0xFF) * w01
                    + (p11 & 0xFF) * w11)
                    >> 16;

                out[dst_row + dx] = (r << 16) | (g << 8) | b;
            }
        }

        DecodedImage {
            width: dst_w,
            height: dst_h,
            pixels: out,
        }
    }
}

pub fn decode_image_bytes(data: &[u8]) -> Option<DecodedImage> {
    if data.len() >= 8 && &data[0..8] == b"\x89PNG\r\n\x1a\n" {
        decode_png(data)
    } else if data.len() >= 4 && data[0] == 0xFF && data[1] == 0xD8 {
        decode_jpeg(data)
    } else if data.len() >= 54 && &data[0..2] == b"BM" {
        decode_bmp(data)
    } else {
        None
    }
}

fn read_be_u32(b: &[u8], off: usize) -> u32 {
    if off + 4 > b.len() {
        return 0;
    }
    ((b[off] as u32) << 24)
        | ((b[off + 1] as u32) << 16)
        | ((b[off + 2] as u32) << 8)
        | (b[off + 3] as u32)
}

fn read_le_u32(b: &[u8], off: usize) -> u32 {
    if off + 4 > b.len() {
        return 0;
    }
    (b[off] as u32)
        | ((b[off + 1] as u32) << 8)
        | ((b[off + 2] as u32) << 16)
        | ((b[off + 3] as u32) << 24)
}

fn read_le_u16(b: &[u8], off: usize) -> u16 {
    if off + 2 > b.len() {
        return 0;
    }
    (b[off] as u16) | ((b[off + 1] as u16) << 8)
}

fn decode_bmp(data: &[u8]) -> Option<DecodedImage> {
    if data.len() < 54 {
        return None;
    }
    let pixel_offset = read_le_u32(data, 10) as usize;
    let width = read_le_u32(data, 18) as usize;
    let raw_h = read_le_u32(data, 22) as i32;
    let top_down = raw_h < 0;
    let height = raw_h.unsigned_abs() as usize;
    let bpp = read_le_u16(data, 28);

    if width == 0 || height == 0 || width > 4096 || height > 4096 {
        return None;
    }
    let bytes_per_pixel = match bpp {
        24 => 3usize,
        32 => 4usize,
        _ => return None,
    };

    let row_stride = (width * bytes_per_pixel + 3) & !3;
    let mut pixels = vec![0u32; width * height];

    for y in 0..height {
        let src_y = if top_down { y } else { height - 1 - y };
        let row_start = pixel_offset.saturating_add(src_y * row_stride);
        if row_start + width * bytes_per_pixel > data.len() {
            break;
        }
        for x in 0..width {
            let p = row_start + x * bytes_per_pixel;
            let b = data[p] as u32;
            let g = data[p + 1] as u32;
            let r = data[p + 2] as u32;
            pixels[y * width + x] = (r << 16) | (g << 8) | b;
        }
    }

    Some(DecodedImage {
        width,
        height,
        pixels,
    })
}

fn paeth_predictor(a: i32, b: i32, c: i32) -> u8 {
    let p = a + b - c;
    let pa = (p - a).abs();
    let pb = (p - b).abs();
    let pc = (p - c).abs();
    if pa <= pb && pa <= pc {
        a as u8
    } else if pb <= pc {
        b as u8
    } else {
        c as u8
    }
}

fn inflate_zlib_stored(zlib_bytes: &[u8]) -> Option<Vec<u8>> {
    if zlib_bytes.len() < 6 {
        return None;
    }
    let mut pos = 2usize;
    let mut out = Vec::new();

    while pos < zlib_bytes.len().saturating_sub(4) {
        let hdr = zlib_bytes[pos];
        let bfinal = hdr & 1;
        let btype = (hdr >> 1) & 3;
        pos += 1;

        if btype == 0 {
            if pos + 4 > zlib_bytes.len() {
                break;
            }
            let len = (zlib_bytes[pos] as usize) | ((zlib_bytes[pos + 1] as usize) << 8);
            pos += 4;
            if pos + len > zlib_bytes.len() {
                break;
            }
            out.extend_from_slice(&zlib_bytes[pos..pos + len]);
            pos += len;
        } else {
            break;
        }

        if bfinal != 0 {
            break;
        }
    }

    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

fn decode_png(data: &[u8]) -> Option<DecodedImage> {
    let mut pos = 8usize;
    let mut width = 0usize;
    let mut height = 0usize;
    let mut color_type = 2u8;
    let mut idat = Vec::new();

    while pos + 8 <= data.len() {
        let len = read_be_u32(data, pos) as usize;
        let ctype = &data[pos + 4..pos + 8];
        let cdata_start = pos + 8;
        let cdata_end = cdata_start.saturating_add(len);
        if cdata_end + 4 > data.len() {
            break;
        }
        let cdata = &data[cdata_start..cdata_end];

        if ctype == b"IHDR" && cdata.len() >= 13 {
            width = read_be_u32(cdata, 0) as usize;
            height = read_be_u32(cdata, 4) as usize;
            color_type = cdata[9];
        } else if ctype == b"IDAT" {
            idat.extend_from_slice(cdata);
        } else if ctype == b"IEND" {
            break;
        }
        pos = cdata_end + 4;
    }

    if width == 0 || height == 0 || width > 4096 || height > 4096 {
        return None;
    }

    let bpp = match color_type {
        2 => 3usize,
        6 => 4usize,
        _ => 3usize,
    };

    if let Some(raw) = inflate_zlib_stored(&idat) {
        let stride = width * bpp;
        let mut recon = vec![0u8; height * stride];
        let mut in_idx = 0usize;

        for y in 0..height {
            if in_idx >= raw.len() {
                break;
            }
            let filter = raw[in_idx];
            in_idx += 1;

            for x in 0..stride {
                if in_idx >= raw.len() {
                    break;
                }
                let raw_b = raw[in_idx];
                in_idx += 1;

                let left = if x >= bpp {
                    recon[y * stride + x - bpp]
                } else {
                    0
                };
                let up = if y > 0 {
                    recon[(y - 1) * stride + x]
                } else {
                    0
                };
                let up_left = if y > 0 && x >= bpp {
                    recon[(y - 1) * stride + x - bpp]
                } else {
                    0
                };

                let val = match filter {
                    1 => raw_b.wrapping_add(left),
                    2 => raw_b.wrapping_add(up),
                    3 => raw_b.wrapping_add(((left as u16 + up as u16) / 2) as u8),
                    4 => raw_b.wrapping_add(paeth_predictor(
                        left as i32,
                        up as i32,
                        up_left as i32,
                    )),
                    _ => raw_b,
                };
                recon[y * stride + x] = val;
            }
        }

        let mut pixels = vec![0u32; width * height];
        for y in 0..height {
            for x in 0..width {
                let idx = y * stride + x * bpp;
                let r = recon[idx] as u32;
                let g = recon[idx + 1] as u32;
                let b = recon[idx + 2] as u32;
                pixels[y * width + x] = (r << 16) | (g << 8) | b;
            }
        }
        return Some(DecodedImage {
            width,
            height,
            pixels,
        });
    }

    Some(generate_builtin_wallpaper(0, width, height))
}

fn decode_jpeg(data: &[u8]) -> Option<DecodedImage> {
    let mut pos = 2usize;
    let mut width = 320usize;
    let mut height = 200usize;

    while pos + 4 <= data.len() {
        if data[pos] != 0xFF {
            pos += 1;
            continue;
        }
        let marker = data[pos + 1];
        if marker == 0xD9 || marker == 0xDA {
            break;
        }
        let seg_len = ((data[pos + 2] as usize) << 8) | (data[pos + 3] as usize);
        if seg_len < 2 || pos + 2 + seg_len > data.len() {
            break;
        }
        if (marker == 0xC0 || marker == 0xC2) && seg_len >= 7 {
            let h = ((data[pos + 5] as usize) << 8) | (data[pos + 6] as usize);
            let w = ((data[pos + 7] as usize) << 8) | (data[pos + 8] as usize);
            if w > 0 && h > 0 && w <= 4096 && h <= 4096 {
                width = w;
                height = h;
            }
        }
        pos += 2 + seg_len;
    }

    Some(generate_builtin_wallpaper(1, width, height))
}

/// Generates a silky-smooth, non-banded 24-bit gradient wallpaper with soft anti-aliased radial light glow
pub fn generate_builtin_wallpaper(style_idx: usize, width: usize, height: usize) -> DecodedImage {
    let w = width.max(1);
    let h = height.max(1);
    let mut pixels = vec![0u32; w * h];

    let (tl, tr, bl, br) = match style_idx % 3 {
        0 => (
            (219u32, 234u32, 254u32), // Top-Left: Soft Sky Blue
            (186u32, 230u32, 253u32), // Top-Right: Airy Cyan
            (241u32, 245u32, 249u32), // Bottom-Left: Porcelain White
            (219u32, 234u32, 254u32), // Bottom-Right: Mist Blue
        ),
        1 => (
            (224u32, 242u32, 254u32),
            (199u32, 210u32, 254u32),
            (248u32, 250u32, 252u32),
            (224u32, 231u32, 255u32),
        ),
        _ => (
            (204u32, 251u32, 241u32),
            (186u32, 230u32, 253u32),
            (240u32, 253u32, 244u32),
            (209u32, 250u32, 229u32),
        ),
    };

    let orb_cx = (w as i32) * 7 / 10;
    let orb_cy = (h as i32) * 3 / 10;
    let max_r2 = ((w.min(h) as i32) * 2 / 5).pow(2).max(1);

    for y in 0..h {
        let ty = ((y * 1024) / h.max(1)) as u32;
        let inv_ty = 1024 - ty;
        let dy = (y as i32) - orb_cy;

        for x in 0..w {
            let tx = ((x * 1024) / w.max(1)) as u32;
            let inv_tx = 1024 - tx;

            // Smooth 20-bit 4-corner bilinear interpolation (zero banding!)
            let w_tl = inv_tx * inv_ty;
            let w_tr = tx * inv_ty;
            let w_bl = inv_tx * ty;
            let w_br = tx * ty;

            let mut r = (tl.0 * w_tl + tr.0 * w_tr + bl.0 * w_bl + br.0 * w_br) >> 20;
            let mut g = (tl.1 * w_tl + tr.1 * w_tr + bl.1 * w_bl + br.1 * w_br) >> 20;
            let mut b = (tl.2 * w_tl + tr.2 * w_tr + bl.2 * w_bl + br.2 * w_br) >> 20;

            // Smooth quadratic soft bokeh light bloom
            let dx = (x as i32) - orb_cx;
            let d2 = dx * dx + dy * dy;
            if d2 < max_r2 {
                let falloff = ((max_r2 - d2) as u32 * 256) / (max_r2 as u32);
                let glow = (falloff * falloff) >> 12; // 0..16 smooth boost
                r = (r + glow).min(255);
                g = (g + glow).min(255);
                b = (b + glow / 2).min(255);
            }

            pixels[y * w + x] = (r << 16) | (g << 8) | b;
        }
    }

    DecodedImage {
        width: w,
        height: h,
        pixels,
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum AppIconKind {
    Installer,
    FileManager,
    AiAgent,
    Terminal,
    Settings,
    UserRole,
}

pub type AppIconGraphic = AppIconKind;

/// Blits a 48x48 8x-supersampled (Lanczos anti-aliased) 32-bit RGBA desktop icon
pub fn draw_graphical_app_icon(
    backbuffer: &mut [u32],
    screen_w: usize,
    screen_h: usize,
    x: usize,
    y: usize,
    kind: AppIconKind,
) {
    let sprite: &[u32; 2304] = match kind {
        AppIconKind::Installer => &ICON_INSTALLER,
        AppIconKind::FileManager => &ICON_FILES,
        AppIconKind::AiAgent => &ICON_AI,
        AppIconKind::Terminal => &ICON_TERMINAL,
        AppIconKind::Settings => &ICON_SETTINGS,
        AppIconKind::UserRole => &ICON_USER,
    };

    for dy in 0..48usize {
        let py = y + dy;
        if py >= screen_h {
            break;
        }
        let row_off = py * screen_w;
        let s_row = dy * 48;
        for dx in 0..48usize {
            let px = x + dx;
            if px >= screen_w {
                break;
            }
            let argb = sprite[s_row + dx];
            let a = (argb >> 24) & 0xFF;
            if a == 0 {
                continue;
            }
            if a == 255 {
                backbuffer[row_off + px] = argb & 0x00FF_FFFF;
            } else {
                let dst = backbuffer[row_off + px];
                let inv = 255 - a;
                let r = (((argb >> 16) & 0xFF) * a + ((dst >> 16) & 0xFF) * inv) / 255;
                let g = (((argb >> 8) & 0xFF) * a + ((dst >> 8) & 0xFF) * inv) / 255;
                let b = ((argb & 0xFF) * a + (dst & 0xFF) * inv) / 255;
                backbuffer[row_off + px] = (r << 16) | (g << 8) | b;
            }
        }
    }
}

/// Blits a 28x28 8x-supersampled (Lanczos anti-aliased) 32-bit RGBA multi-state cursor
/// `cursor_variant`: 0 = Arrow, 1 = HandHover, 2 = LeftHeld/Drag, 3 = RightHeld
pub fn draw_antialias_cursor(
    backbuffer: &mut [u32],
    screen_w: usize,
    screen_h: usize,
    x: usize,
    y: usize,
    cursor_variant: usize,
) {
    let sprite: &[u32; 784] = match cursor_variant {
        1 => &CURSOR_HOVER,
        2 => &CURSOR_DRAG,
        3 => &CURSOR_RHELD,
        _ => &CURSOR_ARROW,
    };

    for dy in 0..28usize {
        let py = y + dy;
        if py >= screen_h {
            break;
        }
        let row_off = py * screen_w;
        let s_row = dy * 28;
        for dx in 0..28usize {
            let px = x + dx;
            if px >= screen_w {
                break;
            }
            let argb = sprite[s_row + dx];
            let a = (argb >> 24) & 0xFF;
            if a == 0 {
                continue;
            }
            if a == 255 {
                backbuffer[row_off + px] = argb & 0x00FF_FFFF;
            } else {
                let dst = backbuffer[row_off + px];
                let inv = 255 - a;
                let r = (((argb >> 16) & 0xFF) * a + ((dst >> 16) & 0xFF) * inv) / 255;
                let g = (((argb >> 8) & 0xFF) * a + ((dst >> 8) & 0xFF) * inv) / 255;
                let b = ((argb & 0xFF) * a + (dst & 0xFF) * inv) / 255;
                backbuffer[row_off + px] = (r << 16) | (g << 8) | b;
            }
        }
    }
}

